(window.AUDIO_PAK = window.AUDIO_PAK || {})["er-is-iets-kapot"] = {"verteller|-10%|de verwarming": "data:audio/mpeg;base64,", "verteller|-10%|de kraan": "data:audio/mpeg;base64,", "verteller|-10%|lekken": "data:audio/mpeg;base64,", "verteller|-10%|de lamp": "data:audio/mpeg;base64,", "verteller|-10%|het raam": "data:audio/mpeg;base64,", "verteller|-10%|repareren": "data:audio/mpeg;base64,", "verteller|-10%|de monteur": "data:audio/mpeg;base64,", "verteller|-10%|De verwarming doet het niet.": "data:audio/mpeg;base64,", "verteller|-10%|De kraan lekt.": "data:audio/mpeg;base64,", "verteller|-10%|Het raam is kapot.": "data:audio/mpeg;base64,", "verteller|-10%|Kan een monteur komen?": "data:audio/mpeg;base64,", "verteller|-10%|Wanneer kunt u het repareren?": "data:audio/mpeg;base64,", "erik|-10%|Reparatiedienst, met Erik.": "data:audio/mpeg;base64,", "erik|-10%|Sinds wanneer?": "data:audio/mpeg;base64,", "erik|-10%|Wat vervelend. Er komt morgen een monteur.": "data:audio/mpeg;base64,", "erik|-10%|Tussen acht en twaalf uur.": "data:audio/mpeg;base64,", "verteller|-10%|de schimmel": "data:audio/mpeg;base64,", "verteller|-10%|vochtig": "data:audio/mpeg;base64,", "verteller|-10%|de wasmachine": "data:audio/mpeg;base64,", "verteller|-10%|het stopcontact": "data:audio/mpeg;base64,", "verteller|-10%|de verhuurder": "data:audio/mpeg;base64,", "verteller|-10%|langskomen": "data:audio/mpeg;base64,", "verteller|-10%|Er zit schimmel in de badkamer.": "data:audio/mpeg;base64,", "verteller|-10%|De muur is vochtig.": "data:audio/mpeg;base64,", "verteller|-10%|Het stopcontact werkt niet.": "data:audio/mpeg;base64,", "verteller|-10%|Kunt u langskomen?": "data:audio/mpeg;base64,", "verteller|-10%|Ik heb de verhuurder gebeld.": "data:audio/mpeg;base64,", "erik|-10%|Goedemorgen. Wat is er aan de hand?": "data:audio/mpeg;base64,", "erik|-10%|Is de muur ook vochtig?": "data:audio/mpeg;base64,", "erik|-10%|Zet u het raam open na het douchen?": "data:audio/mpeg;base64,", "erik|-10%|Dan kijken we ernaar. Is er nog iets?": "data:audio/mpeg;base64,", "erik|-10%|Oké. Wanneer kunnen we langskomen?": "data:audio/mpeg;base64,", "erik|-10%|Prima, dan komen we donderdag.": "data:audio/mpeg;base64,", "verteller|-10%|de foto": "data:audio/mpeg;base64,", "verteller|-10%|het onderhoud": "data:audio/mpeg;base64,", "verteller|-10%|de melding": "data:audio/mpeg;base64,", "verteller|-10%|De kraan in de keuken lekt.": "data:audio/mpeg;base64,", "verteller|-10%|Er zit schimmel op de muur.": "data:audio/mpeg;base64,", "verteller|-10%|Ik maak een foto en stuur een melding.": "data:audio/mpeg;base64,", "verteller|-10%|De monteur komt morgen langs.": "data:audio/mpeg;base64,", "erik|-10%|Reparatiedienst, goedemorgen.": "data:audio/mpeg;base64,", "erik|-10%|Wat is er kapot?": "data:audio/mpeg;base64,", "erik|-10%|Waar in het huis?": "data:audio/mpeg;base64,", "erik|-10%|Kunt u een foto sturen via de app?": "data:audio/mpeg;base64,", "erik|-10%|Wanneer bent u thuis?": "data:audio/mpeg;base64,", "erik|-10%|Dan komt de monteur morgen. Fijne dag!": "data:audio/mpeg;base64,", "erik|+0%|Reparatiedienst, met Erik.": "data:audio/mpeg;base64,", "fatima|+0%|Hallo, met Fatima. Er komt water uit de wasmachine. De vloer is helemaal nat.": "data:audio/mpeg;base64,", "erik|+0%|Doe eerst de kraan van de wasmachine dicht.": "data:audio/mpeg;base64,", "fatima|+0%|Dat heb ik al gedaan.": "data:audio/mpeg;base64,", "erik|+0%|Goed zo. Is de wasmachine van u of van ons?": "data:audio/mpeg;base64,", "fatima|+0%|Van mij.": "data:audio/mpeg;base64,", "erik|+0%|Dan moet u zelf een monteur bellen. Maar de kraan is van ons. Stuur een foto via de app, dan kijken we of hij kapot is.": "data:audio/mpeg;base64,", "fatima|+0%|Oké, ik maak meteen een foto.": "data:audio/mpeg;base64,", "erik|-10%|Wat is er kapot? Beschrijf het probleem.": "data:audio/mpeg;base64,", "verteller|-10%|De kraan in de keuken lekt sinds gisteren. Ik stuur een foto.": "data:audio/mpeg;base64,"};
